node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 2').all();
  console.log(t.name + ':', JSON.stringify(rows, null, 2));
}
" 2>/dev/null || node -e "
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('/workspace/world.db');
db.all(\"SELECT name FROM sqlite_master WHERE type='table'\", (err, tables) => {
  console.log('Tables:', tables);
  tables.forEach(t => {
    db.all('SELECT * FROM ' + t.name + ' WHERE 1 LIMIT 2', (err, rows) => {
      console.log(t.name + ':', JSON.stringify(rows, null, 2));
    });
  });
});
" 2>/dev/null || echo "No Node.js SQLite available"
